<link rel="stylesheet" href="<?=asset('css/newsletter.css')?>">
<main class="write-main nl-main"><div class="writer-head"><div><span class="writer-kicker">Private subscription record</span><h1><?=e($subscriber['name']?:'Subscription preferences')?></h1><p><?=e($subscriber['email'])?></p></div><a class="wbtn" href="<?=url('/write/newsletter/subscribers')?>">All subscribers</a></div>
<?php foreach(flashes()as$flash):?><div class="notice <?=$flash['type']==='error'?'error':''?>"><?=e($flash['message'])?></div><?php endforeach;?><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?>
<section class="nl-card"><dl class="nl-meta"><dt>Subscription</dt><dd><?=e(ucfirst($subscriber['status']))?></dd><dt>Requested</dt><dd><?=e($subscriber['requested_at'])?></dd><dt>Confirmed</dt><dd><?=e($subscriber['confirmed_at']?:'—')?></dd><dt>Unsubscribed</dt><dd><?=e($subscriber['unsubscribed_at']?:'—')?></dd><dt>Consent version</dt><dd><?=e($subscriber['consent_version'])?> · revision <?=intval($subscriber['consent_revision'])?></dd><dt>Newsletter suppression</dt><dd><?=e($subscriber['suppression_reason']?:'None')?><?=!empty($subscriber['suppression_note'])?' — '.e($subscriber['suppression_note']):''?></dd><dt>Provider suppression</dt><dd><?=function_exists('email_address_suppressed')&&email_address_suppressed($subscriber['email'])?'Active; delivery is blocked':'None recorded'?></dd></dl><p class="nl-help">Subscription timestamps use <?=e((string)app_config('timezone','Africa/Nairobi'))?>. Clearing a manual suppression never confirms a subscription or removes a provider suppression.</p></section>
<div class="nl-stats nl-section"><form class="nl-card" method="post" action="<?=url('/write/newsletter/subscribers/'.$subscriber['id'])?>"><?=csrf_field()?><input type="hidden" name="action" value="unsubscribe"><input type="hidden" name="consent_revision" value="<?=intval($subscriber['consent_revision'])?>"><h2>Unsubscribe</h2><p>Stop newsletter delivery. A future subscription will require a fresh email confirmation.</p><button class="wbtn" type="submit">Unsubscribe this address</button></form>
<?php if(!$subscriber['suppressed_at']):?><form class="nl-card" method="post" action="<?=url('/write/newsletter/subscribers/'.$subscriber['id'])?>"><?=csrf_field()?><input type="hidden" name="action" value="suppress"><input type="hidden" name="consent_revision" value="<?=intval($subscriber['consent_revision'])?>"><h2>Suppress delivery</h2><div class="field"><label for="nl-suppress-note">Reason · private</label><textarea id="nl-suppress-note" name="note" maxlength="500" required></textarea></div><button class="wbtn" type="submit">Suppress and unsubscribe</button></form>
<?php elseif($subscriber['suppression_reason']==='manual'):?><form class="nl-card" method="post" action="<?=url('/write/newsletter/subscribers/'.$subscriber['id'])?>"><?=csrf_field()?><input type="hidden" name="action" value="clear_suppression"><input type="hidden" name="consent_revision" value="<?=intval($subscriber['consent_revision'])?>"><h2>Clear manual suppression</h2><p>The address stays unsubscribed and must request and confirm a new subscription.</p><div class="field"><label for="nl-clear-note">Reason · private</label><textarea id="nl-clear-note" name="note" maxlength="500" required></textarea></div><button class="wbtn" type="submit">Clear manual suppression</button></form><?php endif;?></div>
<details class="nl-card nl-section"><summary>Subscription history</summary><ol class="nl-history"><?php foreach($events as$event):?><li><strong><?=e(ucfirst(str_replace('_',' ',$event['event_type'])))?></strong><p><?=e($event['note'])?></p><small><?=e(newsletter_local_time($event['created_at']))?></small></li><?php endforeach;?></ol></details>
</main>
